FUNCTION_BLOCK FB_NestedLoopControl
VAR
    i : INT;
    j : INT;
    flag : BOOL;
    count : INT := 0;
    some_var : INT;
END_VAR

VAR CONSTANT
    MAX_OUTER_ITERATIONS : INT := 10;
    MAX_INNER_ITERATIONS : INT := 46; // (100 - 10) / 2 = 45, plus 1 for inclusive range
END_VAR

VAR
    inner_iterations : INT;
END_VAR

BEGIN
    // Initialize the count to zero at the start of the function block execution
    count := 0;

    // Outer loop iterating from 0 to 10
    FOR i := 0 TO MAX_OUTER_ITERATIONS DO
        // Reset inner loop iteration counter
        inner_iterations := 0;

        // Inner loop iterating from 10 to 100 with a step size of 2
        FOR j := 10 TO 100 BY 2 DO
            // Check if the flag is TRUE
            IF flag THEN
                // Exit the inner loop if the flag is TRUE
                EXIT;
            END_IF;

            // Increment the inner loop iteration counter
            inner_iterations := inner_iterations + 1;
        END_FOR

        // Update the count with the number of times the inner loop executed
        count := count + inner_iterations;

        // Ensure the count does not exceed the expected maximum of iterations
        IF count > MAX_OUTER_ITERATIONS * MAX_INNER_ITERATIONS THEN
            count := MAX_OUTER_ITERATIONS * MAX_INNER_ITERATIONS;
        END_IF;
    END_FOR
END_FUNCTION_BLOCK
